cd /c/Users/usuario/AppData/Local/Temp/claude/081ea1635fc6c07b/d9992a1c-1222-4795-8987-afdf1a8020db/scratchpad; cat > esc.js <<'EOF'
const fs=require('fs');
const O={},N={};
for(const f of fs.readdirSync('old').filter(f=>f.startsWith('esc_'))){
 const t=fs.readFileSync('old/'+f,'utf8').split('\n');let cur=null;
 for(const l of t){const h=l.match(/^### (ESC-\d+)/);if(h){cur=h[1];O[cur]={f,letters:new Set(),tbl:0,lines:0,bul:0,text:''};continue}
  if(!cur)continue;const o=O[cur];o.text+=l+'\n';o.lines++;
  const m=l.match(/^\s*- \(([a-z]+\d?)\)/);if(m)o.letters.add(m[1]);
  if(/^\|/.test(l)&&!/^\|\s*-/.test(l))o.tbl++;
  if(/^- \*\*Dado\*\*/.test(l))o.bul++;}
}
for(const f of fs.readdirSync('new').filter(f=>f.startsWith('esc_'))){
 for(const l of fs.readFileSync('new/'+f,'utf8').split('\n')){const m=l.match(/^\|\s*(ESC-\d+)(?:\s+([a-z]+\d?))?\s/);if(m){const e=N[m[1]]??={f:new Set(),rows:0,letters:new Set(),text:''};e.f.add(f);e.rows++;if(m[2])e.letters.add(m[2]);e.text+=l+'\n'}}}
const out=[];
for(const k of Object.keys(O)){const o=O[k],n=N[k];const oc=Math.max(o.letters.size,o.bul,o.tbl-1>0?o.tbl-1:0,1);
 out.push([k,oc,[...o.letters].join(''),o.bul,o.tbl,n?n.rows:'MISSING',n?[...n.letters].join(''):'',n?[...n.f].join(','):'']);}
console.log('ESC id | oldCases(letters) bul tbl | newRows newLetters');
for(const r of out) if(r[5]==='MISSING'||r[5]<r[1]) console.log(r.join(' | '));
console.log('old total',out.length,'newkeys',Object.keys(N).length);
console.log('in new only', Object.keys(N).filter(k=>!O[k]).join(' '));
EOF
