const fs=require('fs');
const norm=s=>s.replace(/\s+/g,' ').replace(/[“”]/g,'"');
const all=d=>fs.readdirSync(d).filter(f=>f.endsWith('.md')).map(f=>fs.readFileSync(d+'/'+f,'utf8')).join('\n');
const newAll=norm(all('new'));
function lits(t){const s=new Set();
 for(const m of t.matchAll(/`([^`\n]{2,})`/g))s.add(m[1].trim());
 for(const m of t.matchAll(/"([^"\n]{3,80})"/g))s.add(m[1].trim());
 for(const m of t.matchAll(/(?<![\w.-])\d+(?:[.,]\d+)?\s?(?:%|ms|s\b|KB|MB|caracteres|palabras|tokens|minutos|segundos|horas|días|USD|bytes|líneas)/g))s.add(m[0].trim());
 return s}
const mode=process.argv[2];
let missing=[];
for(const f of fs.readdirSync('old').filter(f=>f.endsWith('.md'))){
 const t=fs.readFileSync('old/'+f,'utf8');
 for(const l of lits(t)) if(!newAll.includes(norm(l))) missing.push([f,l]);}
const seen=new Set();
for(const [f,l] of missing){const k=f+'|'+l;if(seen.has(k))continue;seen.add(k);console.log(f.replace('esc_','')+' :: '+l.slice(0,160))}
console.log('TOTAL',seen.size);
EOF
